Creating a complex smart contract involves coding a set of rules that automatically enforce and execute the terms of an agreement between parties on the Ethereum blockchain. Below is a hypothetical example of a complex smart contract written in Solidity, the programming language for Ethereum smart contracts:

```solidity
pragma solidity ^0.8.0;

contract ComplexSmartContract {
    // Define the parties involved
    address public partyA;
    address public partyB;
    address public arbiter;

    // Define the state variables
    uint256 public amount;
    uint256 public deadline;
    mapping(address => uint256) public balances;
    bool public isAgreementActive;

    // Define the events to be emitted
    event AgreementSigned(address indexed partyA, address indexed partyB, uint256 amount, uint256 deadline);
    event AgreementFulfilled(address indexed partyA, address indexed partyB, uint256 amount);
    event AgreementTerminated(address indexed partyA, address indexed partyB);

    // Constructor to set the initial parties and agreement parameters
    constructor(address _partyA, address _partyB, uint256 _amount, uint256 _deadline) {
        partyA = _partyA;
        partyB = _partyB;
        amount = _amount;
        deadline = _deadline;
        balances[partyA] = 0;
        balances[partyB] = 0;
        isAgreementActive = true;
        arbiter = msg.sender;
    }

    // Modifier to check if the caller is the arbiter
    modifier onlyArbiter() {
        require(msg.sender == arbiter, "Only the arbiter can call this function.");
        _;
    }

    // Function to sign the agreement
    function signAgreement() public {
        require(isAgreementActive, "Agreement is not active.");
        require(block.timestamp <= deadline, "Agreement deadline has passed.");
        isAgreementActive = false;
        emit AgreementSigned(partyA, partyB, amount, deadline);
    }

    // Function to fulfill the agreement
    function fulfillAgreement() public onlyArbiter {
        require(!isAgreementActive, "Agreement is already fulfilled.");
        require(block.timestamp >= deadline, "Agreement deadline has not passed.");
        partyA.transfer(amount);
        partyB.transfer(amount);
        isAgreementActive = true;
        emit AgreementFulfilled(partyA, partyB, amount);
    }

    // Function to terminate the agreement
    function terminateAgreement() public onlyArbiter {
        require(!isAgreementActive, "Agreement is already terminated.");
        require(block.timestamp >= deadline, "Agreement deadline has not passed.");
        isAgreementActive = true;
        emit AgreementTerminated(partyA, partyB);
    }

    // Function to deposit funds to the contract
    function deposit() public payable {
        require(msg.value > 0, "Deposit amount must be greater than zero.");
        require(isAgreementActive, "Agreement must be active to deposit funds.");
        balances[msg.sender] += msg.value;
    }

    // Function to withdraw funds from the contract
    function withdraw(uint256 amount) public {
        require(balances[msg.sender] >= amount, "Insufficient balance.");
        require(isAgreementActive, "Agreement must be active to withdraw funds.");
        payable(msg.sender).transfer(amount);
        balances[msg.sender] -= amount;
    }

    // Function to transfer funds to the contract
    function transferFunds(address payable recipient, uint256 amount) public {
        require(isAgreementActive, "Agreement must be active to transfer funds.");
        require(balances[msg.sender] >= amount, "Insufficient balance.");
        recipient.transfer(amount);
        balances[msg.sender] -= amount;
    }
}
```

This smart contract example includes the following features:

1. Parties involved: partyA, partyB, and an arbiter.
2. State variables: amount, deadline, balances, and agreement status.
3. Events for agreement signing, fulfillment, and termination.
4. Constructor to initialize parties and agreement parameters.
5. Functions to sign, fulfill, and terminate the agreement, as well as deposit, withdraw, and transfer funds.
6. Modifiers to enforce access control and ensure proper function execution.

Please note that this is a simplified example, and real-world smart contracts often involve more complex features, such as security checks, gas optimization, and integration with other contracts and services. It's also essential to thoroughly test and audit smart contracts before deploying them to the mainnet to prevent potential vulnerabilities and bugs.

